"""RUN-005 Phase N: writes 56b-policy-decision-detail.md from the policy table in 56 plus hand-written rationale, financial examples and implications. Every decision stays OPEN. Idempotent. Audit tooling only."""
import csv, os, re, collections
os.chdir(r'C:\Users\Yousef\Desktop\Projects\POSS\audit-reports\full-financial-system-discovery-2026-11-25')
s56 = open('56-accounting-policy-decision-package.md', encoding='utf-8').read()
rows = {}
for line in s56.split('\n'):
    m = re.match(r'\| (POL-\d+) \| (.*?) \| (.*?) \| (.*?) \| (.*?) \| (.*?) \|$', line)
    if m:
        rows[m.group(1)] = dict(title=m.group(2), options=m.group(3), evidence=m.group(4), findings=m.group(5), default=m.group(6))
tasks = list(csv.DictReader(open('57-future-remediation-task-register.csv', encoding='utf-8')))
regs = list(csv.DictReader(open('59-post-remediation-regression-test-register.csv', encoding='utf-8')))
D = {
 'POL-01': dict(why='Payment basis matches the GL, which already posts revenue at payment; the other reports then reconcile to it with a labelled bridge.', ex='Sales 517,000 (tax-inclusive, unpaid included) vs Profitability 470,000 (net, unpaid included) vs GL 290,000: tax 47,000 + unpaid 180,000 explain the gap; under option (b) all three show 290,000 net.', rep='Sales, Profitability, KPI and order statistics change on deploy; every revenue figure gets a basis label; VAT figures are unaffected (they come from the GL).', hist='No stored data changes; communicate the change of displayed totals.', mig='None (queries and labels).'),
 'POL-02': dict(why='Discount-first is the usual VAT base (tax on the amount actually charged) and matches the UI preview.', ex='Gross 10,000, 10% discount, 14% VAT: discount-first tax 1,260 (total 10,260) vs current 1,400 (total 10,400): 140 over-declared VAT per such invoice; RUN-005 real-UI: UI 630.00 vs stored 700.00 on 5,000.', rep='VAT payable, invoice totals, AR and revenue split change for discounted lines; VAT return totals must be reviewed per period.', hist='Posted invoices keep their tax; produce an exception report and correct through approved reversing journals.', mig='Replace the line-total triggers (migrations 141/142 logic) with a new migration; recalculate drafts only.'),
 'POL-03': dict(why='Perpetual inventory gives a true COGS and a balance-sheet inventory that equals the stock ledger.', ex='Inventory valuation 132,840 vs GL 1130 -96,120 (difference 228,960) because purchases are expensed to 5110 and waste posts nothing.', rep='COGS, gross profit, balance sheet inventory, valuation and turnover reports change.', hist='Opening-stock journal and a catch-up of purchases already expensed; accountant approval.', mig='Posting-rule changes and a data-correction script; no new columns required.'),
 'POL-04': dict(why='The indirect method derived from GL cash and bank movements is checkable against the cash accounts.', ex='Clean tenant: report 69,290 vs cash change 74,480 (residual 5,190 = working-capital terms); RUN-004: a 20,000 asset purchase paid in cash shows investing +20,000 instead of -20,000.', rep='Cash-flow statement and the predictive cash flow (F-045) must use the same method.', hist='None stored; historical statements differ when regenerated.', mig='None.'),
 'POL-05': dict(why='An open-period rule is the baseline control for any ledger; it prevents 2019 or 2030 postings with no period.', ex='Journals dated 2019-01-15 and 2030-06-01 were posted with no fiscal period.', rep='Period close, trial balance cut-offs and VAT filing windows depend on it.', hist='List entries outside any period; decide per entry.', mig='Fiscal-period tables and a guard in the posting path.'),
 'POL-06': dict(why='Reversing journals preserve the audit trail and restock keeps inventory true.', ex='Refund of a 110.00 paid order (100 net + 10 VAT, COGS 40): Dr revenue 100, Dr VAT payable 10, Cr cash 110; Dr inventory 40, Cr COGS 40.', rep='Sales, profitability, VAT and cash reports must exclude refunded amounts consistently.', hist='None (new capability).', mig='Refund tables and status values.'),
 'POL-07': dict(why='A clearing account settled by an explicit bank deposit shows timing differences and fees.', ex='Card sale 110.00 debits 1113; a settlement deposit of 107.80 (2% fee) must move 110.00 out of 1113 with 2.20 to fees.', rep='Balance sheet (1113 balance), cash reports and bank reconciliation.', hist='Opening reconciliation of existing 1113 balances.', mig='Settlement tables.'),
 'POL-08': dict(why='Accruing at approval puts the expense in the right period and exposes unpaid payroll as a liability.', ex='Salary gross 6,000, deductions 750, net 5,250: accrual Dr 5210 6,000 / Cr 2110 750 and payable 5,250; payment Dr payable / Cr cash 5,250.', rep='P&L by period, balance sheet liabilities, HR cost report.', hist='Salaries 1 and 2 were paid without approval (list for sign-off).', mig='Payment records and accrual posting.'),
 'POL-09': dict(why='Drafts are working documents; ledger effects belong to issued documents.', ex='Draft invoice INV-2026-00005 (5,200) posted Dr 1120 5,200 / Cr 4100 4,500 / Cr 2120 700 at creation.', rep='AR aging, revenue and VAT are overstated while drafts exist.', hist='Reverse journals of existing drafts after listing them.', mig='None (posting trigger point moves).'),
 'POL-10': dict(why='Rejecting under a row lock is simplest; customer credit can be an explicit later feature.', ex='Five parallel receipts of 1,000 on a 3,000 invoice were all accepted: 5,000 received, 2,000 over-collected.', rep='AR subledger vs GL 1120 (residual 1,800 in RUN-003).', hist='List over-settled invoices; decide refund or credit per case.', mig='None (locking and validation).'),
 'POL-11': dict(why='One functional currency per tenant read by every formatter prevents symbol drift.', ex='POS shows $12.00 and $10,000.00 while the dashboard shows EGP 110.00 for the same tenant.', rep='All money displays and exports.', hist='None.', mig='Tenant currency setting.'),
 'POL-12': dict(why='A single GL-derived source removes the competing revenue and cash figures.', ex='KPI net profit 181,540 vs P&L 167,180 (difference 14,360); KPI cash position 50,000 vs GL cash 276,270.', rep='Dashboards and KPI endpoints.', hist='None.', mig='None.'),
 'POL-13': dict(why='A unique (template, period) key makes the scheduled run idempotent.', ex='Two runs on one day created two journals of the same amount.', rep='Recurring expenses in P&L double.', hist='Reverse duplicate journals.', mig='Unique index.'),
 'POL-14': dict(why='Allowing the excess as unpaid leave keeps the request workflow usable and protects payroll.', ex='Approved 30 days against an allowance of 21: 9 days unpaid (daily rate = base salary / 30).', rep='HR leave balance report (remaining currently clamps to 0) and payroll deductions.', hist='List over-allowance approvals.', mig='Optional unpaid_days column.'),
 'POL-15': dict(why='Least privilege: salary data only for HR and owners; a Cashier role for POS staff.', ex='EMPLOYEE role reads base_salary 5,000 from /hr/employees; MANAGER reads /hr/salaries (RUN-005 matrix).', rep='HR, payroll and user screens.', hist='Review access logs.', mig='Seed new roles for existing tenants.'),
 'POL-16': dict(why='A reservation with expiry prevents both phantom stock consumption and oversell.', ex='The RUN-004 load test created 5,719 unpaid cash orders; tracked stock 12 was consumed by 12 of them regardless of payment.', rep='Inventory, orders and KDS counts.', hist='Review stale unpaid orders.', mig='Expiry job.'),
 'POL-17': dict(why='Opening equity posting at the opening date keeps the bank module and the GL equal.', ex='Bank account opened with 50,000: module balance 50,000, GL contribution 0.', rep='Balance sheet, KPI cash.', hist='Correction journals for existing accounts.', mig='None.'),
 'POL-18': dict(why='A driver receivable makes cash risk visible.', ex='A delivered cash order of 110.00 stays unpaid with no record of the cash the driver holds.', rep='Cash, AR/driver receivable.', hist='Reconcile delivered unpaid orders.', mig='Driver settlement tables.'),
 'POL-19': dict(why='Termination at the last working day keeps payroll and turnover consistent.', ex='Resignation completed with last working day 2026-11-25: employee stays active, turnover 0 instead of 100% for the period.', rep='HR turnover, payroll eligibility.', hist='List completed resignations with active employees.', mig='None.'),
 'POL-20': dict(why='Business days are local; UTC buckets mislead by 2-3 hours.', ex='Same KDS rows: UTC busiest hours 1:7, 20:18, 22:11 vs Cairo 3:7, 22:18, 0:11.', rep='KDS, daily sales and any CURRENT_DATE report; exports.', hist='Recomputed on read; no stored change.', mig='Tenant time-zone setting.'),
 'POL-21': dict(why='Completion only at a zero difference against the GL gives the reconciled flag meaning.', ex='A session with statement 777,777.77 and an invented line completed while the bank ledger balance was 12,000.00.', rep='Bank balance reports and last-reconciled fields.', hist='Re-verify completed sessions against the GL.', mig='Line constraints.'),
 'POL-22': dict(why='A cap plus reason and history keeps extensions accountable.', ex='100,000 days moved a trial end to the year 2300.', rep='Super Admin tenant status.', hist='List tenants beyond the cap.', mig='History table.'),
}
def deps(fs):
    ids = sorted(set(re.findall(r'F-\d{3}', fs)))
    t = [x for x in tasks if x['finding_id'] in ids]
    g = [x for x in regs if x['finding_id'] in ids]
    return ids, t, g
out = ['# 56b - Policy decision detail (RUN-005, all decisions OPEN)', '',
       'Companion to [56](56-accounting-policy-decision-package.md). Built by `tests/build_policy_detail.py`. **No decision is approved**; the recommendation is the auditor\'s proposal with rationale, kept separate from any approved decision. Dependent tasks stay NOT STARTED and policy-dependent calculations in the reports are conditional until a decision is recorded.', '']
for pid in sorted(rows):
    r = rows[pid]; d = D.get(pid, {})
    ids, t, g = deps(r['findings'])
    out += [f'## {pid} - {r["title"]}', f'- **Status:** OPEN', f'- **Current product behaviour / evidence:** {r["evidence"]}', f'- **Business question and alternatives:** {r["options"]}', f'- **Recommended option (proposal):** {r["default"]}', f'- **Rationale:** {d.get("why", "see evidence")}', f'- **Financial example:** {d.get("ex", "see evidence")}', f'- **Tax and report implications:** {d.get("rep", "see findings")}', f'- **Historical data:** {d.get("hist", "assess per finding")}', f'- **Migration or backfill:** {d.get("mig", "see remediation specs")}', f'- **Dependent findings:** {", ".join(ids)}', f'- **Dependent future tasks:** {len(t)} (P0 policy tasks: {sum(1 for x in t if x["phase"].startswith("P0"))}); **future regression tests:** {len(g)}', '']
open('56b-policy-decision-detail.md', 'w', encoding='utf-8').write('\n'.join(out))
print(len(rows), 'policies written')
